466	/* --- Scheduling preferences ---------------------------------------------
467	 * Everything the planner's controls set, as opposed to *what* is on the grid
468	 * (the favourites, stored separately under their own TTL). Written after every
469	 * refresh() and read back at boot, so a reload returns the plan the visitor had
470	 * shaped rather than the defaults. */
471	function savePlanPrefs() {
472	  try {
473	    localStorage.setItem(
474	      PREFS_KEY,
475	      JSON.stringify({
476	        v: 1,
477	        d0: state.d0,
478	        d1: state.d1,
479	        dayStartMin: state.dayStartMin,
480	        dayEndMin: state.dayEndMin,
481	        mode: state.mode,
482	        meals: state.mealBreaks.map((m) => ({
483	          id: m.id,
484	          enabled: m.enabled,
485	          startMin: m.startMin,
486	          endMin: m.endMin,
487	        })),
488	        arrival: { ...state.arrival },
489	        departure: { ...state.departure },
490	        forced: [...state.forced],
491	        pacing: { gap: $("ctlGap").value, max: $("ctlMax").value, min: $("ctlMin").value },
492	      })
493	    );
494	  } catch (err) {
495	    console.warn("Fringe Planner: couldn't save scheduling preferences", err);
496	  }
497	}
498	
499	/* refresh() runs once per pointer-frame while the date window is dragged, and
500	 * localStorage writes are synchronous — so the save trails the interaction
501	 * rather than riding inside it. */
502	let prefsSaveTimer = null;
503	function schedulePrefsSave() {
504	  if (prefsSaveTimer) clearTimeout(prefsSaveTimer);
505	  prefsSaveTimer = setTimeout(() => {
506	    prefsSaveTimer = null;
507	    savePlanPrefs();
508	  }, 400);
509	}
510	
511	/* Land a pending debounced save before the page goes away, so preferences
512	 * changed in the last moments of a visit aren't the ones that get lost. */
513	function flushPlanPrefs() {
514	  if (!prefsSaveTimer) return;
515	  clearTimeout(prefsSaveTimer);
516	  prefsSaveTimer = null;
517	  savePlanPrefs();
518	}
519	
520	/* Read the stored preferences back into state. Every field is validated and
521	 * clamped against the same bounds its control enforces: anything missing,
522	 * malformed or out of range leaves that preference at its default rather than
523	 * failing the whole restore, so one bad value can't cost the visitor the rest. */
524	function restorePlanPrefs() {
525	  let data;
526	  try {
527	    data = JSON.parse(localStorage.getItem(PREFS_KEY) || "null");
528	  } catch {
529	    return; // private mode, or a hand-edited value — the defaults are fine
530	  }
531	  if (!data || data.v !== 1) return;
532	
533	  const int = (v, lo, hi, fallback) => (Number.isFinite(v) ? clamp(Math.round(v), lo, hi) : fallback);
534	
535	  // d1 first: it's the ceiling d0 is clamped against, so a stored window can
536	  // never restore inverted.
537	  state.d1 = int(data.d1, 1, DAYS_IN_MONTH, state.d1);
538	  state.d0 = int(data.d0, 1, state.d1, state.d0);
539	  state.dayStartMin = int(data.dayStartMin, 0, DAY_END_CEIL - 15, state.dayStartMin);
540	  state.dayEndMin = int(data.dayEndMin, state.dayStartMin + 15, DAY_END_CEIL, state.dayEndMin);
541	  if (MODE_META[data.mode]) state.mode = data.mode;
542	
543	  if (Array.isArray(data.meals)) {
544	    // Matched by id rather than position, so reordering or adding a meal break
545	    // doesn't misapply a stored one.
546	    for (const meal of state.mealBreaks) {
547	      const saved = data.meals.find((m) => m && m.id === meal.id);
548	      if (!saved) continue;
549	      meal.enabled = Boolean(saved.enabled);
550	      meal.endMin = int(saved.endMin, 5, 1440, meal.endMin);
551	      meal.startMin = int(saved.startMin, 0, meal.endMin - 5, meal.startMin);
552	    }
553	  }
554	  if (data.arrival) {
555	    state.arrival.enabled = Boolean(data.arrival.enabled);
556	    state.arrival.endMin = int(data.arrival.endMin, 0, DAY_END_CEIL, state.arrival.endMin);
557	  }
558	  if (data.departure) {
559	    state.departure.enabled = Boolean(data.departure.enabled);
560	    state.departure.startMin = int(data.departure.startMin, 0, DAY_END_CEIL, state.departure.startMin);
561	  }
562	  // Must-sees are re-filtered against the catalogue when the favourites land
563	  // (applyFavourites' keepForced path), so a pin on a show no longer on the
564	  // grid drops itself there rather than needing a check here.
565	  if (Array.isArray(data.forced)) {
566	    state.forced = new Map(
567	      data.forced.filter(
568	        (e) => Array.isArray(e) && typeof e[0] === "string" && (e[1] === true || typeof e[1] === "string")
569	      )
570	    );
571	  }
572	  if (data.pacing) restorePacingControls(data.pacing);
573	  syncPlanControls();
574	}
575	
576	/* The three pacing controls keep their value in the DOM rather than in `state`,
577	 * so they restore by writing it back — and only if the control still offers it,
578	 * so an option that has since been renamed falls back to the markup's default
