// Pick favourite slugs that make each board constraint (day start/end, lunch,
// dinner, arrival, departure) exclude at least one show, using the real engine.
import { readFileSync } from "node:fs";
import { rehydrateShows } from "/home/user/EdFringeNow/plan/lib/hydrate.js";
import { placementDiagnostics } from "/home/user/EdFringeNow/plan/lib/engine.js";

const wire = JSON.parse(readFileSync("/home/user/EdFringeNow/data/normalized/shows.min.json", "utf8"));
const venues = JSON.parse(readFileSync("/home/user/EdFringeNow/data/venues.json", "utf8"));
const avail = JSON.parse(readFileSync("/home/user/EdFringeNow/data/normalized/availability.min.json", "utf8"));
const shows = rehydrateShows(wire, venues, 2026, avail);
console.log("hydrated shows:", shows.length);

const opts = {
  dateStart: "2026-08-08",
  dateEnd: "2026-08-09",
  dayStartMin: 10 * 60,
  dayEndMin: 22 * 60,
  mealBreaks: [
    { id: "lunch", enabled: true, startMin: 12 * 60 + 30, endMin: 13 * 60 + 30 },
    { id: "dinner", enabled: true, startMin: 18 * 60, endMin: 19 * 60 },
  ],
  arrival: { date: "2026-08-08", endMin: 11 * 60 + 30 },
  departure: { date: "2026-08-09", startMin: 20 * 60 },
};

const diag = placementDiagnostics(shows, opts);
const take = (list, n) => list.slice(0, n).map((s) => s.slug);
const picks = {
  dayStart: take(diag.dayStart, 2),
  dayEnd: take(diag.dayEnd, 2),
  lunch: take(diag.meals.lunch || [], 2),
  dinner: take(diag.meals.dinner || [], 2),
  arrival: take(diag.arrival, 2),
  departure: take(diag.departure, 2),
};
console.log(JSON.stringify(picks, null, 2));

// A few placeable shows to fill the grid too.
const blocked = diag.blockedSlugs;
const fine = shows
  .filter((s) => !blocked.has(s.slug) && (s.performances || []).some((p) => p.date >= opts.dateStart && p.date <= opts.dateEnd && p.available))
  .slice(0, 6)
  .map((s) => s.slug);
console.log("fine:", JSON.stringify(fine));

const all = [...new Set([...Object.values(picks).flat(), ...fine])];
console.log("ALL", JSON.stringify(all));

