const require = createRequire("/opt/node22/lib/node_modules/playwright/");
const { chromium } = require("playwright");

const SLUGS = [
  "a-little-green-leaf", "a-political-breakfast", "be-good-with-paulette", "hysterical",
  "borderlandscomedy", "some-guy-called-dave-joke-of-the-fringe-showcase",
  "100-million-fish-in-the-aquarium", "15-minutes-of-shame",
  "shorn-by-elsa-mctaggart", "a-microscopic-odyssey",
  "abandoman-afterglow", "alice-fraser-oh-man",
  "2026-greek-comedian-of-the-year-george-zacharopoulos-the-meaning-of-life-maybe",
  "earnest", "100-things-you-are-overthinking-an-improv-stand-up-comedy-game-show",
];

const PREFS = {
  v: 1, d0: 8, d1: 9,
  dayStartMin: 600, dayEndMin: 1320,
  meals: [
    { id: "lunch", enabled: true, startMin: 750, endMin: 810 },
    { id: "dinner", enabled: true, startMin: 1080, endMin: 1140 },
  ],
  arrival: { enabled: true, endMin: 690 },
  departure: { enabled: true, startMin: 1200 },
  forced: [],
};

const browser = await chromium.launch({ args: ["--no-sandbox"] });
const page = await (await browser.newContext({ viewport: { width: 1500, height: 1100 } })).newPage();
const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });

await page.goto("http://localhost:8080/terms.html");
await page.evaluate(([slugs, prefs]) => {
  localStorage.setItem("edfringe.plan.favourites.v1", JSON.stringify({ v: 1, slugs, filename: "smoke.html", savedAt: Date.now() }));
  localStorage.setItem("edfringe.plan.prefs.v1", JSON.stringify(prefs));
}, [SLUGS, PREFS]);

await page.goto("http://localhost:8080/plan/");
await page.waitForSelector(".sch-dayline--start .dl-flag", { timeout: 30000 });
await page.waitForTimeout(1200);

const board = page.locator("#scheduleWrap");
await board.screenshot({ path: "/tmp/claude-0/-home-user-EdFringeNow/bfb0ced7-ec3f-56c7-82f9-fef8bb9228b7/scratchpad/board.png" });

// Zoom on the labels: report what each pill contains and whether triangles are present.
const report = await page.evaluate(() => {
  const txt = (sel) => [...document.querySelectorAll(sel)].map((el) => ({
    text: el.textContent.trim(),
    mark: !!el.querySelector(".excl-mark"),
    excl: el.querySelector(".excl-mark")?.getAttribute("aria-label") || null,
  }));
  return {
    flags: txt(".dl-flag"),
    meals: txt(".meal-label"),
    trips: txt(".sch-trip-label"),
  };
});
console.log(JSON.stringify(report, null, 2));

// Hover a triangle to capture the excludes popup.
const mark = page.locator(".meal-label .excl-mark").first();
if (await mark.count()) {
  await mark.hover();
  await page.waitForTimeout(400);
  await board.screenshot({ path: "/tmp/claude-0/-home-user-EdFringeNow/bfb0ced7-ec3f-56c7-82f9-fef8bb9228b7/scratchpad/board-popup.png" });
}

