import { createRequire } from "node:module";
const require = createRequire("/opt/node22/lib/node_modules/playwright/");
const { chromium } = require("playwright");

const browser = await chromium.launch({ args: ["--no-sandbox"] });
const page = await (await browser.newContext({ viewport: { width: 1500, height: 1100 } })).newPage();
const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));

await page.goto("http://localhost:8080/plan/");
await page.waitForSelector(".sch-dayline--start .dl-grip", { timeout: 30000 });
await page.waitForTimeout(800);

const dragBy = async (sel, dy) => {
  const box = await page.locator(sel).first().boundingBox();
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  await page.mouse.down();
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2 + dy, { steps: 6 });
  await page.mouse.up();
  await page.waitForTimeout(400);
};

const state = async () => page.evaluate(() => ({
  start: document.querySelector(".sch-dayline--start .dl-flag")?.textContent.trim(),
  startMark: !!document.querySelector(".sch-dayline--start .dl-flag .excl-mark"),
  lunch: document.querySelector('.sch-meal[data-meal="lunch"] .meal-label')?.textContent.trim(),
  lunchMark: !!document.querySelector('.sch-meal[data-meal="lunch"] .meal-label .excl-mark'),
  arrive: document.querySelector(".sch-trip--arrival .sch-trip-label")?.textContent.trim(),
  arriveMark: !!document.querySelector(".sch-trip--arrival .sch-trip-label .excl-mark"),
}));

console.log("before:", JSON.stringify(await state()));
await dragBy(".sch-dayline--start .dl-grip", 40);
await dragBy('.sch-meal[data-meal="lunch"]', -30);
await dragBy(".sch-trip--arrival .meal-resize--bottom", 30);
console.log("after: ", JSON.stringify(await state()));
console.log("page errors:", errors.length ? errors : "none");
await browser.close();

