1	// Main API the UI calls: matching favourites against the show catalogue,
2	// summarizing availability within a date/time window, and (for later use) the
3	// scheduling primitives ported from edfringe/scheduling.py.
4	//
5	// Pure — no DOM, no fetch. The UI is responsible for loading data/normalized/
6	// shows.json and the favourites file text and passing them in.
7	
8	import { urlFromSlug } from "./favourites.js";
9	import {
10	  isAvailable,
11	  isNonTicketed,
12	  dateTimeToMinutes,
13	  timeToMinutesOfDay,
14	} from "./availability.js";
15	import { travelMinutes, DEFAULT_TRAVEL_MODE } from "./travel.js";
16	
17	// --- indexing / matching --------------------------------------------------
18	
19	/**
20	 * Index shows by slug for O(1) favourite lookup.
21	 * @param {object[]} shows shows.json array
22	 * @returns {Map<string, object>}
23	 */
24	export function buildIndex(shows) {
25	  const index = new Map();
26	  for (const show of shows || []) {
27	    if (show && show.slug) index.set(show.slug, show);
28	  }
29	  return index;
30	}
31	
32	/**
33	 * Resolve favourite slugs against the show index.
34	 * @param {string[]} slugs de-duplicated slugs from parseFavourites
35	 * @param {Map<string, object>} index from buildIndex
36	 * @returns {{matched: object[], missingSlugs: string[]}}
37	 */
38	export function matchFavourites(slugs, index) {
39	  const matched = [];
40	  const missingSlugs = [];
41	  for (const slug of slugs || []) {
42	    const show = index.get(slug);
43	    if (show) matched.push(show);
44	    else missingSlugs.push(slug);
45	  }
46	  return { matched, missingSlugs };
47	}
48	
49	// --- summarizing availability within a window -----------------------------
50	
51	/**
52	 * Normalize a startTimeMin/Max filter bound to minutes-since-midnight: pass
53	 * through a number as-is, or parse an "HH:MM" string.
54	 * @param {number|string} bound
55	 * @returns {number}
56	 */
57	function normalizeTimeBound(bound) {
58	  if (typeof bound === "number") return bound;
59	  if (typeof bound === "string") return timeToMinutesOfDay(bound);
60	  throw new TypeError(`Expected number or "HH:MM" string, got ${JSON.stringify(bound)}`);
61	}
62	
63	/**
64	 * Annotate every performance of every show against a date/time-of-day window,
65	 * and roll up summary counts.
66	 *
67	 * @param {object[]} shows shows to summarize (typically matchFavourites(...).matched)
68	 * @param {{dateStart: string, dateEnd: string, startTimeMin: number|string, startTimeMax: number|string}} filter
69	 *   dateStart/dateEnd are "YYYY-MM-DD" (inclusive). startTimeMin/startTimeMax are
70	 *   either minutes-since-midnight or "HH:MM" strings (inclusive).
71	 * @param {number} [totalFavourites] total favourite slugs before matching (defaults
72	 *   to shows.length when the caller only has the matched set on hand).
73	 * @returns {{
74	 *   counts: {totalFavourites: number, matchedShows: number, showsAvailableInWindow: number},
75	 *   shows: Array<{
76	 *     slug: string, title: string,
77	 *     performances: Array<{date: string, start: string, available: boolean, status: string|null, soldOut: boolean, inWindow: boolean}>,
78	 *     availableDateSpan: {min: string, max: string} | null,
79	 *   }>,
80	 * }}
81	 */
82	export function summarize(shows, filter, totalFavourites) {
83	  const dateStart = filter.dateStart;
84	  const dateEnd = filter.dateEnd;
85	  const startTimeMin = normalizeTimeBound(filter.startTimeMin);
86	  const startTimeMax = normalizeTimeBound(filter.startTimeMax);
87	
88	  const summarizedShows = (shows || []).map((show) => {
89	    let availableMin = null;
90	    let availableMax = null;
91	    let hasInWindow = false;
92	
93	    const performances = (show.performances || []).map((perf) => {
94	      const available = isAvailable(perf);
95	      if (available) {
96	        if (availableMin === null || perf.date < availableMin) availableMin = perf.date;
97	        if (availableMax === null || perf.date > availableMax) availableMax = perf.date;
98	      }
99	      const dateInRange = perf.date >= dateStart && perf.date <= dateEnd;
100	      const startMinOfDay = timeToMinutesOfDay(perf.start);
101	      const timeInRange = startMinOfDay >= startTimeMin && startMinOfDay <= startTimeMax;
102	      const inWindow = available && dateInRange && timeInRange;
103	      if (inWindow) hasInWindow = true;
104	      return {
105	        date: perf.date,
106	        start: perf.start,
107	        available,
108	        status: perf.status ?? null,
109	        soldOut: !!perf.soldOut,
110	        inWindow,
111	      };
112	    });
113	
114	    return {
115	      slug: show.slug,
116	      title: show.title,
117	      performances,
118	      availableDateSpan: availableMin ? { min: availableMin, max: availableMax } : null,
119	      _hasInWindow: hasInWindow, // internal, stripped before returning below
120	    };
121	  });
122	
123	  const showsAvailableInWindow = summarizedShows.filter((s) => s._hasInWindow).length;
124	  for (const s of summarizedShows) delete s._hasInWindow;
125	
126	  return {
127	    counts: {
128	      totalFavourites: totalFavourites ?? (shows ? shows.length : 0),
129	      matchedShows: shows ? shows.length : 0,
130	      showsAvailableInWindow,
131	    },
132	    shows: summarizedShows,
133	  };
134	}
135	
136	// --- scheduling primitives (for later use) ---------------------------------
137	// Ported from edfringe/scheduling.py. Default trip window and gap match the
138	// Python module's defaults for 2026; all are overridable parameters here
139	// rather than module-level globals (Python's `configure()`).
140	
141	export const DEFAULT_WINDOW_START = "2026-08-07T15:00";
142	export const DEFAULT_WINDOW_END = "2026-08-24T17:00";
143	export const DEFAULT_MIN_GAP_SAME_VENUE = 0;
144	export const DEFAULT_MIN_GAP_DIFFERENT_VENUE = 30;
145	
146	// A Fringe evening runs past midnight: a performance that starts before this
147	// clock time (05:00) belongs to the PREVIOUS calendar day's festival night,
148	// drawn near the top of that day's 09:00–27:00 schedule column rather than at
149	// the bottom of its own morning. Folding adds 1440 to its minute-of-day (so
150	// 00:45 → 24:45) and re-dates it to the night before. 05:00 is a safe cutoff —
151	// nothing in the catalogue starts between 01:00 and 08:59.
152	export const NIGHT_FOLD_CUTOFF_MIN = 5 * 60;
