156	  const [y, m, d] = dateISO.split("-").map(Number);
157	  const dt = new Date(Date.UTC(y, m - 1, d - 1));
158	  const p2 = (n) => String(n).padStart(2, "0");
159	  return `${dt.getUTCFullYear()}-${p2(dt.getUTCMonth() + 1)}-${p2(dt.getUTCDate())}`;
