162	/**
163	 * A performance's "festival night" placement. A show starting after midnight is
164	 * folded onto the previous evening: same real wall-clock start/end (kept for
165	 * exports and chronological ordering), but a festival date one day earlier and a
166	 * minute-of-day past 24:00 so it lands at the top of that night's column.
167	 * @param {string} date real "YYYY-MM-DD"
168	 * @param {number} startMinuteOfDay real minutes-since-midnight of the start
169	 * @param {number} cutoffMin fold shows starting before this clock minute
170	 * @returns {{festivalDate: string, festivalStartMinute: number}}
171	 */
172	export function festivalNight(date, startMinuteOfDay, cutoffMin = NIGHT_FOLD_CUTOFF_MIN) {
173	  if (startMinuteOfDay < cutoffMin) {
174	    return { festivalDate: previousDate(date), festivalStartMinute: startMinuteOfDay + 1440 };
175	  }
176	  return { festivalDate: date, festivalStartMinute: startMinuteOfDay };
177	}
